SELECT company, no, latest_node latestNode, trace_json traceJson
FROM trade_logistics
WHERE order_id = #{orderId}
AND tenant_id = #{tenantId}
ORDER BY cache_time DESC
LIMIT 1

SELECT t.order_id orderId, t.company, t.no, t.latest_node latestNode, t.trace_json traceJson
FROM trade_logistics t
WHERE t.order_id IN

    #{id}

AND t.tenant_id = #{tenantId}
AND t.cache_time = (
    SELECT MAX(cache_time) FROM trade_logistics WHERE order_id = t.order_id
)
